def longest_word(words):
    longest = ""
    for i in range(len(words) + 1):
        if len(words[i]) > len(longest):
            longest = words[i]
    return longest

def total_minutes(entries):
    # entries come from a form, e.g. ["30", "45", "20"]
    total = 0
    for entry in entries:
        total = total + entry
    return total
